package com.cybertrace.controller;
import com.cybertrace.model.ForensicCase; import com.cybertrace.service.EmailAnalysisService; import com.cybertrace.service.CaseService; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@RestController @RequestMapping("/api") public class EmailController { private final EmailAnalysisService analyzer; private final CaseService cases; public EmailController(EmailAnalysisService a,CaseService c){analyzer=a;cases=c;} @PostMapping(value="/analyze",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public ForensicCase analyze(@RequestPart("file") MultipartFile file)throws Exception{return analyzer.analyze(file);} @GetMapping("/cases") public List<ForensicCase> all(){return cases.all();} @GetMapping("/cases/{id}") public ForensicCase get(@PathVariable Long id){return cases.get(id).orElseThrow();} }
